import React, { useEffect, useMemo, useState } from "react";
import { motion } from "framer-motion";

/* STAFF NAVBAR */
import StaffNavbar from "../components/StaffNavbar";

const STAFF_BASE = "http://localhost/GitHub/Capstone--Development/staff";

const formatCurrency = value => `₱${Number(value || 0).toLocaleString()}`;
const formatDate = value => {
  if (!value) return "N/A";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "N/A";
  return date.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
};

export default function Customers() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");

  const fetchOrders = () => {
    fetch(`${STAFF_BASE}/api_orders.php`)
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) {
          setOrders(data);
        } else {
          setOrders([]);
        }
      })
      .catch(() => setOrders([]))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    fetchOrders();
  }, []);

  const customers = useMemo(() => {
    const map = {};

    orders.forEach(order => {
      const email = (order.email || "").trim().toLowerCase();
      if (!email) return;

      const name = order.customer || "Unknown";
      const orderDate = order.created_at || order.order_date || "";
      const orderTime = new Date(orderDate).getTime();

      if (!map[email]) {
        map[email] = {
          name,
          email,
          orders: 0,
          totalSpent: 0,
          lastOrder: orderDate,
          lastStatus: order.status || "Pending",
        };
      }

      const customer = map[email];
      customer.orders += 1;
      customer.totalSpent += Number(order.total || 0);

      if (
        orderTime &&
        (!customer.lastOrder || orderTime > new Date(customer.lastOrder).getTime())
      ) {
        customer.lastOrder = orderDate;
        customer.lastStatus = order.status || customer.lastStatus;
      }
    });

    return Object.values(map).sort((a, b) => b.totalSpent - a.totalSpent);
  }, [orders]);

  const filteredCustomers = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (!query) return customers;

    return customers.filter(customer =>
      customer.name.toLowerCase().includes(query) ||
      customer.email.toLowerCase().includes(query)
    );
  }, [customers, search]);

  const totalRevenue = useMemo(
    () => orders.reduce((sum, order) => sum + Number(order.total || 0), 0),
    [orders]
  );

  const returningCustomers = useMemo(
    () => customers.filter(customer => customer.orders > 1).length,
    [customers]
  );

  const weeklyOrders = useMemo(
    () =>
      orders.filter(order => {
        const date = new Date(order.created_at || order.order_date || "");
        if (Number.isNaN(date.getTime())) return false;
        const diffDays = (new Date() - date) / 86400000;
        return diffDays <= 7;
      }).length,
    [orders]
  );

  return (
    <div className="bg-[#fafafa] min-h-screen font-['Inter']">
      <StaffNavbar />

      <div className="p-8 xl:p-10 pt-28">
        <div className="mb-10">
          <p className="text-[10px] uppercase tracking-[0.3em] text-gray-400">
            Staff Control Panel
          </p>
          <h1 className="text-3xl font-bold">Customer Management</h1>
          <p className="mt-2 text-gray-500 max-w-2xl">
            Review customer engagement, order history, and top spenders from the current order database.
          </p>
        </div>

        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4 mb-10">
          <motion.div whileHover={{ y: -4 }} className="rounded-[30px] border border-gray-100 bg-white p-6 shadow-sm">
            <p className="text-xs uppercase tracking-[0.3em] text-gray-400 mb-3">Total customers</p>
            <h2 className="text-4xl font-bold text-black">{customers.length}</h2>
          </motion.div>

          <motion.div whileHover={{ y: -4 }} className="rounded-[30px] border border-gray-100 bg-white p-6 shadow-sm">
            <p className="text-xs uppercase tracking-[0.3em] text-gray-400 mb-3">Returning customers</p>
            <h2 className="text-4xl font-bold text-black">{returningCustomers}</h2>
          </motion.div>

          <motion.div whileHover={{ y: -4 }} className="rounded-[30px] border border-gray-100 bg-white p-6 shadow-sm">
            <p className="text-xs uppercase tracking-[0.3em] text-gray-400 mb-3">Orders this week</p>
            <h2 className="text-4xl font-bold text-black">{weeklyOrders}</h2>
          </motion.div>

          <motion.div whileHover={{ y: -4 }} className="rounded-[30px] border border-gray-100 bg-white p-6 shadow-sm">
            <p className="text-xs uppercase tracking-[0.3em] text-gray-400 mb-3">Total revenue</p>
            <h2 className="text-4xl font-bold text-black">{formatCurrency(totalRevenue)}</h2>
          </motion.div>
        </div>

        <div className="mb-8 grid gap-4 md:grid-cols-[1fr_auto] items-end">
          <div>
            <p className="text-[#d4af37] text-[10px] uppercase tracking-[0.35em] mb-3">
              Customer directory
            </p>
            <h2 className="text-4xl font-serif font-bold tracking-tight">
              Customer list and order stats
            </h2>
          </div>
          <div className="space-y-3 sm:flex sm:items-center sm:gap-3 sm:space-y-0">
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search name or email"
              className="w-full rounded-2xl border border-gray-200 bg-white px-4 py-3 text-sm text-gray-700 outline-none focus:border-black sm:w-80"
            />
            <button
              onClick={() => setSearch("")}
              className="rounded-2xl border border-gray-200 bg-white px-4 py-3 text-sm text-gray-700 transition hover:border-black"
            >
              Clear
            </button>
          </div>
        </div>

        <div className="rounded-[40px] border border-gray-100 bg-white p-6 shadow-xl">
          {loading ? (
            <p className="text-gray-500">Loading customers...</p>
          ) : customers.length === 0 ? (
            <p className="text-gray-500">No customer data available yet.</p>
          ) : filteredCustomers.length === 0 ? (
            <p className="text-gray-500">No customers match your search.</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="min-w-full border-separate border-spacing-y-3 text-left">
                <thead>
                  <tr className="text-sm text-gray-500 uppercase tracking-[0.2em]">
                    <th className="px-4 py-3">Customer</th>
                    <th className="px-4 py-3">Email</th>
                    <th className="px-4 py-3">Orders</th>
                    <th className="px-4 py-3">Spent</th>
                    <th className="px-4 py-3">Last order</th>
                    <th className="px-4 py-3">Status</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredCustomers.map(customer => (
                    <tr key={customer.email} className="border-b border-gray-100">
                      <td className="px-4 py-4 font-semibold text-gray-900">{customer.name}</td>
                      <td className="px-4 py-4 text-sm text-gray-500">{customer.email}</td>
                      <td className="px-4 py-4 text-sm text-gray-700">{customer.orders}</td>
                      <td className="px-4 py-4 text-sm text-gray-900">{formatCurrency(customer.totalSpent)}</td>
                      <td className="px-4 py-4 text-sm text-gray-700">{formatDate(customer.lastOrder)}</td>
                      <td className="px-4 py-4">
                        <span className="inline-flex rounded-full bg-[#e5f3ff] px-3 py-1 text-xs font-semibold uppercase tracking-[0.2em] text-[#2563eb]">
                          {customer.lastStatus || "Pending"}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
